def get_world_map_svg() -> str:
    """Return the full authentic SVG world map string with 176 sovereign countries."""
    paths_html = []
    for code, name, d in COUNTRY_PATHS:
        cls = 'country-path'
        if code in ('IN', 'RU', 'US', 'CN'):
            cls += ' high-activity'
        safe_name = name.replace('"', '&quot;')
        paths_html.append(
            f'<path id="map-{code}" class="{cls}" data-code="{code}" '
            f'data-name="{safe_name}" d="{d}"><title>{safe_name}</title></path>'
        )

    joined_paths = "\n".join(paths_html)

    return f"""<svg id="world-map-svg" viewBox="0 0 1008 651" role="img" aria-label="Global threat telemetry map" preserveAspectRatio="xMidYMid meet">
  <defs>
    <pattern id="map-grid" width="36" height="36" patternUnits="userSpaceOnUse">
      <path d="M 36 0 L 0 0 0 36" fill="none" stroke="rgba(255,255,255,0.035)" stroke-width="0.5"/>
    </pattern>
    <radialGradient id="pulse-grad-in" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#22d3ee" stop-opacity="0.7"/>
      <stop offset="100%" stop-color="#22d3ee" stop-opacity="0"/>
    </radialGradient>
    <radialGradient id="pulse-grad-alert" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#38bdf8" stop-opacity="0.7"/>
      <stop offset="100%" stop-color="#38bdf8" stop-opacity="0"/>
    </radialGradient>
  </defs>

  <!-- Ocean & Technical Grid -->
  <rect width="1008" height="651" fill="var(--map-bg)" />
  <rect width="1008" height="651" fill="url(#map-grid)" />

  <!-- SOC Parallels & Meridians (Subtle Graticules) -->
  <g class="graticules" stroke="var(--map-graticule)" stroke-width="0.5" stroke-dasharray="2 4">
    <line x1="0" y1="160" x2="1008" y2="160" />
    <line x1="0" y1="320" x2="1008" y2="320" />
    <line x1="0" y1="410" x2="1008" y2="410" stroke="var(--cyan)" stroke-opacity="0.3" stroke-dasharray="none" />
    <line x1="0" y1="500" x2="1008" y2="500" />
    <line x1="475" y1="0" x2="475" y2="651" stroke="var(--cyan)" stroke-opacity="0.3" stroke-dasharray="none" />
  </g>

  <!-- Technical Graticule Coordinate Labels -->
  <g class="graticule-labels" fill="var(--dim)" font-size="8" font-family="monospace">
    <text x="8" y="156">60° N</text>
    <text x="8" y="316">30° N</text>
    <text x="8" y="406">0° EQUATOR</text>
    <text x="8" y="496">30° S</text>
    <text x="480" y="14">0° MERIDIAN</text>
  </g>

  <!-- Authentic Sovereign Landmasses -->
  <g id="map-countries">
{joined_paths}
  </g>

  <!-- High-Activity Telemetry Pulse Radii & Markers -->
  <g id="map-markers" pointer-events="none">
    <!-- India (IN) Hub -->
    <circle cx="707" cy="395" r="18" fill="url(#pulse-grad-in)" class="map-pulse" />
    <circle cx="707" cy="395" r="3.5" fill="var(--cyan)" stroke="#fff" stroke-width="1.2" />
    <g transform="translate(707, 420)" class="country-pin">
      <rect x="-46" y="-11" width="92" height="18" rx="3" fill="var(--map-tooltip-bg)" stroke="var(--cyan)" stroke-width="0.8"/>
      <text x="0" y="0" text-anchor="middle" dominant-baseline="central" fill="var(--cyan)" font-size="9" font-family="monospace" font-weight="700">IN (7,682)</text>
    </g>

    <!-- Russia (RU) Hub -->
    <circle cx="730" cy="180" r="16" fill="url(#pulse-grad-alert)" class="map-pulse" />
    <circle cx="730" cy="180" r="3.5" fill="var(--blue)" stroke="#fff" stroke-width="1.2" />
    <g transform="translate(730, 155)" class="country-pin">
      <rect x="-46" y="-11" width="92" height="18" rx="3" fill="var(--map-tooltip-bg)" stroke="var(--blue)" stroke-width="0.8"/>
      <text x="0" y="0" text-anchor="middle" dominant-baseline="central" fill="var(--blue)" font-size="9" font-family="monospace" font-weight="700">RU (5,113)</text>
    </g>

    <!-- United States (US) Hub -->
    <circle cx="210" cy="310" r="16" fill="url(#pulse-grad-alert)" class="map-pulse" />
    <circle cx="210" cy="310" r="3.5" fill="var(--blue)" stroke="#fff" stroke-width="1.2" />
    <g transform="translate(210, 285)" class="country-pin">
      <rect x="-46" y="-11" width="92" height="18" rx="3" fill="var(--map-tooltip-bg)" stroke="var(--blue)" stroke-width="0.8"/>
      <text x="0" y="0" text-anchor="middle" dominant-baseline="central" fill="var(--blue)" font-size="9" font-family="monospace" font-weight="700">US (5,112)</text>
    </g>

    <!-- China (CN) Hub -->
    <circle cx="770" cy="340" r="16" fill="url(#pulse-grad-alert)" class="map-pulse" />
    <circle cx="770" cy="340" r="3.5" fill="var(--blue)" stroke="#fff" stroke-width="1.2" />
    <g transform="translate(770, 315)" class="country-pin">
      <rect x="-46" y="-11" width="92" height="18" rx="3" fill="var(--map-tooltip-bg)" stroke="var(--blue)" stroke-width="0.8"/>
      <text x="0" y="0" text-anchor="middle" dominant-baseline="central" fill="var(--blue)" font-size="9" font-family="monospace" font-weight="700">CN (5,068)</text>
    </g>
  </g>
</svg>"""
